class DatabaseSeeder extends Seeder
{
    private function upsertDataRaw($table, $columns, $values, $uniqueColumns)
    {
        $dbName = env('DB_DATABASE');
        $columnsString = implode(', ', $columns);
        $valuesString = implode(', ', array_map(function($v) { return "('".implode("','", $v)."')"; }, $values));
        $updateString = implode(', ', array_map(function($col) { return "$col = VALUES($col)"; }, array_diff($columns, $uniqueColumns)));

        $sql = "INSERT INTO $dbName.$table ($columnsString) VALUES $valuesString
                ON DUPLICATE KEY UPDATE $updateString";

        DB::unprepared($sql);
    }

    /**
     * Seed the application's database.
     *
     * @return void
     */

public function run()
    {
        $this->seedUsers();
        $this->seedCountries();
        $this->seedHeroes();
        $this->seedBottleSizes();
        $this->seedWarehouses();
        $this->seedPackSizes();
        $this->seedPriceTypes();
        $this->seedWineTypes();
        $this->seedRegions();
        $this->seedWineries();
        $this->seedGrapes();
        $this->seedWineryPhotos();
        $this->seedWines();
        $this->seedWineGrapes();
        $this->seedWinePrices();
 }}

